body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
}

.table-title {
  margin: 0 0 12px;
  font-size: 34px;
  line-height: 1.1;
  font-family: inherit;
}

.filter-row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  font-family: inherit;
}

.filter-row select {
  border: 1px solid #d5dbe3;
  border-radius: 8px;
  padding: 6px 10px;
  background: #ffffff;
  color: #111827;
  font-family: inherit;
}

.table-shell {
  width: 600px;
  max-width: 100%;
}

.handsontableInputHolder,
.handsontableInput {
  opacity: 1 !important;
}

.handsontableInput {
  background: #ffffff !important;
  color: #111827 !important;
  border: 1px solid #276ef1 !important;
  box-shadow: 0 4px 12px rgba(17, 24, 39, 0.18) !important;
}

/* Row striping is not done here on purpose. The theme's own
   `rowCellOddBackgroundColor` / `rowCellEvenBackgroundColor` tokens (see
   src/App.tsx) already stripe the grid, and stating the same two colours again
   in CSS would outrank whatever theme the grid is given — leaving these rows
   light if the theme is swapped for a dark one. */

